// spec: specs/html-rtl-dir.md (3.1–3.2) · кейс: .qa/tests/html-rtl-dir/RTL-DIR-04.md
// seed: tests/seed.spec.ts (гость); /guides — tests/seed.admin.spec.ts (admin, #359741) · прод, только чтение: не-GET обрываются, SW выключен.
// Регресс #9c4736 (глобальный dir=rtl): ничего не уехало за край — комментарий программиста PR #198 «אין גלילה הצידה»,
// карта требований С1. Мобайл — оба телефона (iPhone 375, Pixel 7), десктоп — 1440×900.
import { test, expect, Page } from '@playwright/test';
import { GUEST_PAGES, ADMIN_PAGES, ADMIN_STATE, PageKey, pathOf, prepareReadOnly, dismissPopups, waitReady } from './rtl-dir.helpers';

test.use({ serviceWorkers: 'block' });

async function expectNoHorizontalScroll(page: Page, path: string) {
  const m = await page.evaluate(() => ({
    doc: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    body: document.body.scrollWidth - document.documentElement.clientWidth,
  }));
  expect(m.doc, `${path}: documentElement scrollWidth − clientWidth`).toBeLessThanOrEqual(0);
  expect(m.body, `${path}: body scrollWidth − clientWidth`).toBeLessThanOrEqual(0);
}

for (const device of ['@mobile', '@desktop'] as const) {
  test.describe(`Нет горизонтальной прокрутки после dir=rtl ${device}`, () => {
    for (const key of GUEST_PAGES as PageKey[]) {
      test(`${key}: страница не шире экрана #9c4736 ${device} @prod-safe`, async ({ page, context, request }) => {
        const path = await pathOf(request, key);
        await prepareReadOnly(context);
        await dismissPopups(page);
        await page.goto(path);
        await waitReady(page, key);
        await expectNoHorizontalScroll(page, path);
      });
    }

    test.describe('admin (#359741)', () => {
      test.use({ storageState: ADMIN_STATE });
      for (const key of ADMIN_PAGES) {
        test(`${key} (admin): страница не шире экрана #9c4736 #359741 ${device} @prod-safe`, async ({ page, context, request }) => {
          const path = await pathOf(request, key);
          await prepareReadOnly(context);
          await dismissPopups(page);
          await page.goto(path);
          await waitReady(page, key);
          await expectNoHorizontalScroll(page, path);
        });
      }
    });
  });
}
